using Microsoft.EntityFrameworkCore;
namespace Movers.DAL.Persistence;
public static class WarehouseAttachmentSchema {
 public static Task Apply(MoversDbContext db) {
  var sql = db.Database.IsSqlServer() ? """
IF OBJECT_ID(N'dbo.WarehouseAttachments', N'U') IS NULL
BEGIN
 CREATE TABLE [WarehouseAttachments] ([SerialNo] int IDENTITY PRIMARY KEY, [Id] uniqueidentifier NOT NULL, [TenantId] uniqueidentifier NOT NULL, [ReceiptId] uniqueidentifier NOT NULL, [OriginalFileName] nvarchar(180) NOT NULL, [ContentType] nvarchar(150) NOT NULL, [DeclaredSizeBytes] bigint NOT NULL, [StoredSizeBytes] bigint NULL, [ObjectKey] nvarchar(700) NOT NULL, [UploadedBy] nvarchar(320) NOT NULL, [IsUploaded] bit NOT NULL, [IsDeleted] bit NOT NULL, [UploadedAtUtc] datetimeoffset NULL);
 CREATE UNIQUE INDEX [IX_WarehouseAttachments_Id] ON [WarehouseAttachments] ([Id]);
 CREATE INDEX [IX_WarehouseAttachments_TenantId_ReceiptId] ON [WarehouseAttachments] ([TenantId],[ReceiptId]);
END
""" : db.Database.IsNpgsql() ? """
CREATE TABLE IF NOT EXISTS "WarehouseAttachments" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL UNIQUE, "TenantId" uuid NOT NULL, "ReceiptId" uuid NOT NULL, "OriginalFileName" varchar(180) NOT NULL, "ContentType" varchar(150) NOT NULL, "DeclaredSizeBytes" bigint NOT NULL, "StoredSizeBytes" bigint NULL, "ObjectKey" varchar(700) NOT NULL, "UploadedBy" varchar(320) NOT NULL, "IsUploaded" boolean NOT NULL, "IsDeleted" boolean NOT NULL, "UploadedAtUtc" timestamp with time zone NULL);
CREATE INDEX IF NOT EXISTS "IX_WarehouseAttachments_TenantId_ReceiptId" ON "WarehouseAttachments" ("TenantId", "ReceiptId");
""" : """
CREATE TABLE IF NOT EXISTS "WarehouseAttachments" ("SerialNo" INTEGER PRIMARY KEY AUTOINCREMENT, "Id" TEXT NOT NULL UNIQUE, "TenantId" TEXT NOT NULL, "ReceiptId" TEXT NOT NULL, "OriginalFileName" TEXT NOT NULL, "ContentType" TEXT NOT NULL, "DeclaredSizeBytes" INTEGER NOT NULL, "StoredSizeBytes" INTEGER NULL, "ObjectKey" TEXT NOT NULL, "UploadedBy" TEXT NOT NULL, "IsUploaded" INTEGER NOT NULL, "IsDeleted" INTEGER NOT NULL, "UploadedAtUtc" TEXT NULL);
CREATE INDEX IF NOT EXISTS "IX_WarehouseAttachments_TenantId_ReceiptId" ON "WarehouseAttachments" ("TenantId", "ReceiptId");
""";
  return db.Database.ExecuteSqlRawAsync(sql);
 }
}
